pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 callTime, uint256 value) public {
        // Bound callTime to a reasonable timestamp range to avoid overflow and ensure realistic fuzzing.
        callTime = bound(callTime, 1, type(uint64).max);
        // Bound value to avoid overflow in add_uint256 (balance addition) and ensure we have enough Ether.
        value = bound(value, 0, type(uint128).max);
        // Restrict unlockTime to prevent overflow in the original comparison _unlockTime > block.timestamp
        unlockTime = bound(unlockTime, 0, type(uint64).max);

        // Warp to the fuzzed callTime and set up the actor.
        vm.warp(callTime);
        address actor = makeAddr("actor");
        vm.deal(actor, value);

        // Execute Put from the actor with the fuzzed parameters.
        vm.prank(actor);
        c.Put{value: value}(unlockTime);

        // Compute the expected unlockTime: max(unlockTime, block.timestamp)
        uint256 expected = unlockTime > callTime ? unlockTime : callTime;
        (uint actualUnlockTime, ) = c.Acc(actor);

        // Property: The actual unlockTime must equal the expected unlockTime.
        assertTrue(actualUnlockTime == expected);
    }
}

