pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, uint256 unlockTime, uint256 collectAm) public {
        // am must be at least MinSum (1 ether) and nonzero, collectAm up to am
        vm.assume(am >= 1 ether);
        vm.assume(am <= type(uint128).max); // avoid overflow in add_uint256 for practical amounts
        vm.assume(collectAm > 0);
        vm.assume(collectAm <= am);
        vm.assume(unlockTime <= type(uint128).max);
        // Make block.timestamp at least 1 to trigger the bug's 0 unlockTime collect revert
        vm.warp(1);

        // Fund caller and Put
        address caller = address(0x1234);
        vm.deal(caller, am);
        vm.startPrank(caller);
        c.Put{value: am}(unlockTime);
        vm.stopPrank();

        // Warp to a time strictly greater than unlockTime to ensure reference would allow collect
        // We need to handle the case where unlockTime == 0 (reference also allows collect at t>0)
        // For the bug, unlockTime is always 0, so collect should revert for block.timestamp > 0
        // To make the test generic, we set time forward beyond unlockTime unconditionally
        uint256 collectTime = unlockTime > 0 ? unlockTime + 1 : 1;
        vm.warp(collectTime);

        // Try to Collect and observe outcome
        bool ok;
        vm.prank(caller);
        try c.Collect(collectAm) {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert: Collect should succeed (the reference allows it at t > unlockTime)
        // The buggy version will revert because its unlockTime=0 < block.timestamp (which is >=1)
        assertTrue(ok);
    }
}

