contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, uint256 sendAmount, uint8 unlockTimeOffset) public {
        // 1. Restrict to wide admissible domain: non-zero sendAmount, unlockTimeOffset > 0 so unlockTime > block.timestamp,
        //    and prevent overflow of the addition (the contract asserts c >= a on add_uint256).
        vm.assume(sendAmount > 0);
        vm.assume(unlockTimeOffset > 0);
        vm.assume(initialBalance <= type(uint256).max - sendAmount);

        // 2. Set up an EOA for msg.sender with the given initial balance in the contract.
        address user = address(0x1234);
        vm.deal(user, sendAmount);

        // If initialBalance > 0, we need to Put that into the contract first.
        if (initialBalance > 0) {
            vm.deal(user, initialBalance);
            vm.prank(user);
            c.Put{value: initialBalance}(uint256(block.timestamp + 1));
        }

        // Record balance before the Put call.
        uint256 balanceBefore = c.Acc(user).balance;

        // Execute the fuzzed Put call.
        vm.prank(user);
        c.Put{value: sendAmount}(uint256(block.timestamp + unlockTimeOffset));

        // 3. Assert that the balance increased by exactly sendAmount.
        uint256 balanceAfter = c.Acc(user).balance;
        assertEq(balanceAfter - balanceBefore, sendAmount, "balance increase must equal msg.value");
