contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit) public {
        // Bound deposit to a reasonable range to avoid overflow in attacker logic
        bound(deposit, 1, 100 ether);

        // Deploy reentrant attacker
        Attacker attacker = new Attacker(c);
        uint256 attackerInitialBalance = deposit;
        vm.deal(address(attacker), attackerInitialBalance);

        // Record the balance before the call
        uint256 balanceBefore = address(attacker).balance;

        // Drive the call through the attacker, which will attempt a reentrant Put
        attacker.attack{value: deposit}();

        // After the attack, calculate the Attacker's accrued balance in C
        (uint256 unlockTime, uint256 accBalance) = c.Acc(address(attacker));

        // The Attacker should have unlocked balance immediately because attacker sets unlockTime=0, so block.timestamp>=0
        uint256 unlockedBalance = block.timestamp > unlockTime ? accBalance : 0;

        // The unlocked balance must not exceed the balance before call (which is 0 initially) plus the single Ether sent
        // In the correct version, reentrant Put calls fail due to nonReentrant_, so only one Put succeeds.
        // In the buggy version, reentrant Put calls succeed and double the recorded balance.
        assertTrue(unlockedBalance <= deposit);
    }
}

