pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 firstDeposit, uint256 extraEth) public {
        // Restrict to reasonable values to avoid overflow in added balance
        firstDeposit = bound(firstDeposit, 0, 1 ether);
        extraEth = bound(extraEth, 0, 1 ether);
        vm.assume(firstDeposit > 0); // ensure at least one call happens

        // Attacker contract that reenters c.Put when receiving Ether via its fallback
        // This is the minimal adversarial counterparty required because the bug is
        // reentrancy: an EOA cannot reenter; a helper MUST be deployed.
        ReenteringAttacker attacker = new ReenteringAttacker(c);

        // Fund attacker with some Ether
        vm.deal(address(attacker), firstDeposit + extraEth);

        // Record balance before
        uint256 balanceBefore = c.Acc(address(attacker)).balance;
        uint256 ethSent = firstDeposit; // we'll send exactly this much

        // Attacker calls Put with firstDeposit, which triggers its fallback that calls Put again with extraEth
        vm.prank(address(attacker));
        attacker.attack{value: ethSent}(firstDeposit, extraEth);

        // After the transaction, the correct contract guarantees that Acc.balance
        // equals the single top-level Ether sent (firstDeposit) because the
        // non-reentrant guard prevents the reentrant call from inflating the balance.
        // The buggy version allows the reentrant call to succeed, adding extraEth
        // to the balance without additional Ether, so balance > ethSent.
        uint256 balanceAfter = c.Acc(address(attacker)).balance;
        assertTrue(balanceAfter <= ethSent);
    }
}

contract ReenteringAttacker {
    C target;
    uint256 extraEth;
    bool attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 firstDeposit, uint256 _extraEth) external payable {
        require(msg.value == firstDeposit);
        extraEth = _extraEth;
        attacking = true;
        target.Put{value: firstDeposit}(firstDeposit);
    }

    fallback() external payable {
        if (attacking) {
            attacking = false;
            // Reenter Put with the extraEth value but without sending more Ether
            target.Put(extraEth);
        }
    }
}

