pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 extraAmount) public {
        // amounts must be at least 1 wei and sum <= type(uint256).max / 2 to avoid overflow
        vm.assume(amount > 0 && amount < (type(uint256).max / 2));
        vm.assume(extraAmount > 0 && extraAmount < (type(uint256).max / 2));
        uint256 totalSent = amount + extraAmount;
        vm.assume(totalSent >= amount && totalSent >= extraAmount); // safety

        // Deploy re-entrant attacker that collects and re-enters Put
        ReenteringAttacker attacker = new ReenteringAttacker(c);
        vm.deal(address(attacker), totalSent);

        // Attacker puts initial amount and unlocks it
        vm.prank(address(attacker));
        c.Put{value: amount}(0);
        vm.warp(block.timestamp + 1);

        // Attacker calls Collect with extraAmount, triggering reentrancy
        vm.prank(address(attacker));
        c.Collect{value: 0}(extraAmount);

        // Direct Ether sent = amount + extraAmount (both through Put)
        // Reference: nonReentrant_ blocks reentry, so balance = amount + extraAmount
        // Buggy: nested Put executes, so balance = amount + extraAmount + extraAmount (inflated)
        (,,uint256 balance) = c.Acc(address(attacker));
        assertTrue(balance == totalSent);
    }
}

contract ReenteringAttacker {
    C public target;
    bool private reentered;
    event Log(uint256 val);

    constructor(C _target) {
        target = _target;
        reentered = false;
    }

    // Called by c when Collect performs low-level call with value _am
    receive() external payable {
        if (!reentered) {
            reentered = true;
            uint256 val = msg.value;
            // Re-enter Put with the withdrawn amount
            target.Put{value: val}(0);
        }
    }
}

