pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint256 _putEth, uint256 _collectAmt) public {
        // 1. Admissible domain: keep amounts non-zero and unlock time in the past
        vm.assume(_putEth > 0);
        vm.assume(_collectAmt > 0);
        vm.assume(_collectAmt <= _putEth);
        vm.assume(_unlockTime < block.timestamp);

        // 2. Setup: fund a user, put eth, warp past unlock
        address user = address(0x1234);
        vm.deal(user, _putEth);
        vm.prank(user);
        c.Put{value: _putEth}(_unlockTime);

        vm.warp(block.timestamp + 1);

        uint256 contractBalBefore = address(c).balance;

        // Drive c through Collect
        vm.prank(user);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _collectAmt));
        require(ok, "Collect call failed");

        // 3. General rule: if Collect succeeds, contract's ETH balance must decrease by exactly the collected amount
        uint256 contractBalAfter = address(c).balance;
        assertEq(contractBalBefore - contractBalAfter, _collectAmt, "ETH balance not reduced by collected amount");
    }
}
